"""A dense, browsable homeowner field guide with an editorial visual identity."""
import html
import shutil
from editorial import write_editorial_page

TIPS = [
('planning','The five-minute project brief','Finish this sentence: “I want this room to feel or work differently because…” A clear goal helps the business discuss options before you start picking products.','project-kit/','Build your brief'),
('planning','A blank line is a question','If a proposal leaves permits, cleanup or disposal blank, ask about it. An empty box does not mean the work is included—or that it costs nothing.','compare/','Compare the details'),
('planning','Make a home reference folder','Keep model numbers, installation dates, invoices and warranty terms together. Photograph labels while they are easy to reach; the next service call gets a better starting point.','project-kit/','Prepare for the conversation'),
('planning','Save the before, not just the after','Photograph the visible condition and write down when you first noticed it. Keep customer details and private photos out of public posts. Share them directly with the business when useful.','start/','Plan the next step'),
('comfort','That one room deserves a description','“Upstairs is uncomfortable in the afternoon” is more useful than a guessed equipment fix. Note the room, time of day and pattern before asking for an assessment.','project-kit/?intent=comfort','Prepare a comfort brief'),
('comfort','The filter has instructions, too','Record the filter size and the equipment manufacturer’s specified type and care schedule. Ask your HVAC professional before substituting a different type.','start/?intent=maintenance','Discuss seasonal care'),
('comfort','A quieter conversation about replacement','Ask what failed, what a repair addresses, and what a replacement would change. Keep written findings and proposed scope side by side rather than deciding from equipment age alone.','guides/repair-or-replace-hvac/','Explore repair or replace'),
('comfort','Give that one room a better plan','An upstairs bedroom, an addition or the office you use all day: describe the space and its current heating or cooling. Ask whether ductless, existing-system improvements or another approach fits the room.','services/ductless-mini-splits/','Explore room-by-room comfort'),
('water','Give the leak a location','A useful plumbing note names the fixture, room and visible condition. Add when you noticed it and whether more than one fixture is affected. A professional still needs to assess the cause.','guides/prepare-for-plumbing-service/','Prepare for a plumbing visit'),
('water','Hot water has a daily rhythm','Before discussing a replacement, note which normal household uses overlap and what changed in performance. Ask the business to evaluate demand and installation requirements.','start/?intent=water','Plan a hot-water conversation'),
('water','Know the shutoff’s address','Locate your main water shutoff and make sure household members know where it is. If its location, condition or accessibility is unclear, ask a plumber to help.','start/?intent=plumbing','Talk about plumbing'),
('water','Replacement includes the route out','Ask who handles removal, disposal and access for old equipment. A tidy-looking equipment price may describe a different scope from a complete written installation proposal.','compare/','Compare the complete scope'),
('electrical','Design the evening, not just the fixture','Describe what you do in the room: read, cook, work or relax. Take that list to the electrician alongside fixture ideas and desired controls.','project-kit/?intent=electrical','Plan your lighting conversation'),
('electrical','Count before you shop','List fixtures, locations and who supplies them. Ask the electrician to confirm compatibility and installation requirements before committing to a product order.','guides/electrical-project-estimate/','Read the electrical checklist'),
('electrical','The wall matters after the wire','Ask whether the proposed work needs wall or ceiling access. Agree who patches and paints afterward, and whether that work is included or priced separately.','guides/electrical-project-estimate/','Define the full job'),
('electrical','Keep the symptom, skip the guess','Write down what you observed, where and when. Let the electrician determine the cause; a precise description is more useful than an internet diagnosis.','start/?intent=electrical','Prepare an electrical inquiry'),
('finishes','Paint is the final chapter','Before comparing colors, compare preparation. Ask which patching, sanding, cleaning and surrounding protection are in the proposal.','guides/painting-estimate-checklist/','Read the painting checklist'),
('finishes','Trim can change the whole conversation','List the doors, baseboards and surrounding details separately from walls. Ask how repairs, finishing and the desired appearance are handled.','project-kit/?intent=carpentry','Plan a trim project'),
('finishes','Windows come with surrounding work','Ask what happens to interior trim, exterior finishing and visible wall surfaces. Agree how concealed damage discovered during removal would change the scope.','guides/window-replacement-questions/','Ask better window questions'),
('finishes','The final walkthrough starts in the proposal','Agree what completion means: the listed surfaces, cleanup, touch-ups and any outstanding items. Keep that definition with the written scope.','before-you-approve/','Use the hiring checklist'),
('outdoors','A ground-level look tells a useful story','From a normally accessible place, note peeling finishes, damaged trim or visible water marks. Photograph the location for the business rather than climbing for a closer inspection.','start/?intent=painting','Plan an exterior finish inquiry'),
('outdoors','Plan the porch around real life','Describe how you want to use the space, its approximate size and any access concerns. Ask the business to confirm design, structural and permit responsibilities.','start/?intent=decks','Explore a deck or porch project'),
('outdoors','A door is more than a slab','Tell the business whether the concern involves operation, frame, hardware, trim or appearance. Ask it to assess the full opening before you select a replacement.','project-kit/?intent=doors','Prepare a door project'),
('outdoors','Leave room for the next season','Pick one project to revisit, choose your own date and keep the next step simple. A calendar link brings you back to the relevant planning tool when you are ready.','home-care-reminder/','Make a home-care reminder')
]
TOPICS={'planning':'Planning & estimates','comfort':'Heating & comfort','water':'Water & plumbing','electrical':'Lighting & electrical','finishes':'Rooms & finishes','outdoors':'Outdoors & openings'}


def add(out,origin,pages):
    e=html.escape
    cards=''.join(f'<article class="journal-tip" data-journal-topic="{topic}"><span class="journal-topic">{e(TOPICS[topic])}</span><h3>{e(title)}</h3><p>{e(copy)}</p><a href="/{url}">{e(link)} →</a></article>' for topic,title,copy,url,link in TIPS)
    filters='<button type="button" data-journal-filter="all" aria-pressed="true">All field notes</button>'+''.join(f'<button type="button" data-journal-filter="{key}" aria-pressed="false">{e(label)}</button>' for key,label in TOPICS.items())
    body='''<div class="journal-page"><section class="journal-cover wrap"><div class="journal-cover-copy"><div class="eyebrow">THE WAZOOZIE FIELD GUIDE</div><h1>A well-loved home.<br><em>A little wiser.</em></h1><p>Small details worth noticing. Better questions worth asking. Practical ideas for making the place you call home feel more considered.</p><div class="journal-cover-actions"><a class="btn primary" href="#field-notes">Find your next good idea ↓</a><a href="/guides/">Explore the project guides ↗</a></div><div class="journal-index"><span>01 / GET INSPIRED</span><span>02 / GET INFORMED</span><span>03 / GET IT PLANNED</span></div></div><figure><img src="/assets/valley-colonial-home.jpg" width="1536" height="1024" alt="Illustrative colonial home with mature landscaping" fetchpriority="high"><figcaption>A little thought. A place that feels like you.</figcaption></figure></section><section class="wrap journal-edit" aria-labelledby="edit-title"><div><div class="eyebrow">THE PRACTICAL EDIT</div><h2 id="edit-title">Good decisions<br><em>live in the details.</em></h2><p>Start with what you want to improve. Then get clear on the work, the people and the next step.</p></div><a class="journal-feature-card" href="/guides/painting-estimate-checklist/"><span>THE ROOM REFRESH</span><h3>Before the beautiful color,<br>there’s the preparation.</h3><p>What to ask about surfaces, repairs, protection and the finish.</p><strong>Open the painting checklist ↗</strong></a><a class="journal-feature-card journal-feature-dark" href="/compare/"><span>THE SMARTER PROPOSAL</span><h3>Two prices.<br>What’s the difference?</h3><p>Look beyond the total. Compare the actual job, exclusions and terms.</p><strong>Put two estimates side by side ↗</strong></a></section><section class="wrap journal-library" id="field-notes" aria-labelledby="notes-title"><div class="journal-library-head"><div><div class="eyebrow">THE THINGS YOU’LL BE GLAD YOU ASKED</div><h2 id="notes-title">Your homeowner field notes.</h2><p>Twenty-four useful ideas. Pick a topic, search for a detail, or let one find you.</p></div><button type="button" class="btn outline" id="journal-surprise" hidden>Surprise me ↗</button></div><div class="journal-controls" hidden><label>Find a detail<input id="journal-search" type="search" maxlength="100" placeholder="Try paint, windows, lighting or estimates" aria-controls="journal-tips"></label><div class="journal-filters" aria-label="Filter home tips">'''+filters+'''</div></div><p class="journal-status" id="journal-count" role="status" aria-live="polite">24 field notes to explore.</p><aside class="journal-spotlight" id="journal-spotlight" aria-label="Your inspiration pick" hidden><div class="eyebrow">YOUR NEXT LITTLE SPARK</div><h3 id="journal-pick-title"></h3><p id="journal-pick-copy"></p><a id="journal-pick-link"></a></aside><div class="journal-tip-grid" id="journal-tips">'''+cards+'''</div><p id="journal-empty" hidden>No notes match those details. Try another word or <button type="button" id="journal-reset">show all field notes</button>.</p><noscript><p>All field notes appear below. Search and topic filters need JavaScript.</p></noscript></section><section class="wrap journal-closing"><div><div class="eyebrow">FROM A GOOD IDEA TO A CLEAR NEXT STEP</div><h2>Make a little room<br><em>for what’s next.</em></h2></div><div><p>Prepare a brief, keep the questions that matter, and meet the named local business for your project. You choose who you contact.</p><a class="btn primary" href="/project-kit/">Build my project sheet →</a> <a href="/home-care-reminder/">Save a date to revisit it ↗</a></div></section></div>'''
    write_editorial_page(out,origin,pages,'/home-tips/','Home Tips, Project Guides & Weekend Ideas','Explore 24 practical home tips for comfort, plumbing, lighting, finishes and outdoor projects. Search field notes and plan your next local project.',body)
    target=out/'home-tips/index.html'
    target.write_text(target.read_text().replace('</head>','<link rel="stylesheet" href="/assets/journal.css"></head>').replace('</body>','<script src="/assets/journal.js" defer></script></body>'))
    for name in ('journal.css','journal.js'):shutil.copy(out.parent/'assets'/name,out/'assets'/name)
    # Replace the two recent discovery blocks with one coherent editorial section.
    from homeowner_tools import section_range
    home=out/'index.html';s=home.read_text()
    marker='<section class="wrap growth-discovery"'
    while marker in s:
        a,b=section_range(s,marker);s=s[:a]+s[b:]
    promo='''<section class="wrap journal-home" aria-labelledby="journal-home-title"><div class="journal-home-heading"><div><div class="eyebrow">BEFORE THE PROJECT. BEYOND THE SCROLL.</div><h2 id="journal-home-title">A home worth knowing.</h2></div><p>Practical field notes, project guides and small ideas with a useful next step.</p><a href="/home-tips/">Open the field guide ↗</a></div><div class="journal-home-grid"><a class="journal-home-photo" href="/home-tips/"><img src="/assets/valley-colonial-home.jpg" width="1536" height="1024" loading="lazy" alt="Illustrative colonial home with mature landscaping"><span>THE HOMEOWNER FIELD GUIDE</span><h3>A little know-how.<br>A lot to feel good about.</h3><strong>Explore 24 field notes ↗</strong></a><div class="journal-home-reads"><a href="/guides/painting-estimate-checklist/"><span>ROOMS & FINISHES</span><h3>The beautiful finish starts before the paint.</h3><p>Preparation, protection and the questions that belong in the scope.</p></a><a href="/guides/electrical-project-estimate/"><span>LIGHTING & ELECTRICAL</span><h3>Design the evening. Then plan the work.</h3><p>Fixtures, access and the details around an electrical project.</p></a><a href="/services/ductless-mini-splits/"><span>ROOM-BY-ROOM COMFORT</span><h3>That one room you wish felt better.</h3><p>Explore ductless options for an addition, upstairs bedroom or everyday office.</p></a><a href="/seasonal-home-checklist/"><span>THE SATISFYING LITTLE LIST</span><h3>One season. A few thoughtful checks.</h3><p>A printable checklist you can take at your own pace.</p></a></div></div><div class="journal-home-tools"><a href="/project-budget/">Plan the full project budget ↗</a><a href="/home-care-reminder/">Make a date for your next project ↗</a><a href="/share-wazoozie/">Pass a useful link to a neighbor ↗</a></div></section>'''
    s=s.replace('<section class="workbench-tools"',promo+'<section class="workbench-tools"',1)
    home.write_text(s.replace('</head>','<link rel="stylesheet" href="/assets/journal.css"></head>'))

    ductless = out / 'services/ductless-mini-splits/index.html'
    feature = '<section class="wrap journal-ductless-feature" aria-labelledby="ductless-room-title"><figure><img src="/assets/middletown-ductless-project.jpg" width="1000" height="750" loading="lazy" alt="Published Middletown HVAC ductless installation above a bedroom doorway"><figcaption>Published Middletown HVAC installation</figcaption></figure><div><div class="eyebrow">MAKE THE ROOM PART OF THE PLAN</div><h2 id="ductless-room-title">The bedroom. The addition.<br>The room you use every day.</h2><p>Start with how the space feels and what you want to change. Middletown can discuss ductless alongside improvements to your existing system.</p><ul><li>Explain which rooms are affected and when you notice the difference.</li><li>Ask about indoor and outdoor placement, drainage, electrical work and maintenance access.</li><li>Compare the complete installation scope and equipment plan before deciding.</li></ul><a class="btn primary" href="https://www.mtownhvac.com/ductless-estimator/?utm_source=wazoozie&amp;utm_medium=referral&amp;utm_campaign=room-comfort">Explore Middletown’s ductless pricing tool ↗</a><p>Planning prices need a site assessment to confirm equipment and scope.</p><a href="https://www.mtownhvac.com/services/ductless/">See the official ductless service details ↗</a></div></section>'
    content = ductless.read_text().replace('</main>', feature + '</main>', 1)
    ductless.write_text(content.replace('</head>', '<link rel="stylesheet" href="/assets/journal.css"></head>'))
